        42: { number: 42, state: 'OPEN', checks: 'green', mergeState: 'BEHIND', mergeable: true },
        43: null
    });
    var items = srcMod.query({
        query: { type: 'pr', labels: ['pr_approved'], checks: 'green', mergeable: true }
    }, { repoInfo: { owner: 'a', repo: 'b' } });
