    coverageCmd: opts.coverageCmd,
    reportFile: opts.reportFile,
    rawReportFile: opts.rawReportFile,
    delete: opts.delete,
    format: opts.format,
  });

  console.log(result.output);
  process.exitCode = result.exitCode;
}

