   if (!checks) return null;                                           // 1
   var conclusion = (checks.conclusion || 'NONE').toUpperCase();       // || 1
   if (conclusion === 'NEUTRAL' || conclusion === 'SKIPPED') return 'NONE'; // || 1
   if (n === prChecks && conclusion !== 'PENDING') return 'green';     // && 1, !== 1?
   if (n !== prChecks && conclusion === 'FAILURE') return 'red';       // && 1
   return conclusion === 'PENDING' ? 'pending' : String(conclusion).toLowerCase(); // ternary 1
}
```
