function _ghReviewThreadList(repoInfo, n, cap) {
   var thsRaw = github_list_pr_review_threads({ owner: repoInfo.owner, repo: repoInfo.repo, number: n });
   var ths = asList(parseMcp(thsRaw));
   for (var i = 0; i < ths.length; i++) {
       var th = ths[i];
       if (!(th && (th.path || th.original_path))) continue;
       th.comments = asList(th.comments);
       var resolved = false;                                 // 1
       for (var j = 0; j < th.comments.length; j++) {        // 1
           if (th.comments[j].isResolved) { resolved = true; break; } // 1 + break?
       }
       th.isResolved = resolved;
   }
   ths = ths.filter(function (t) { return t.isResolved !== undefined; }); // cb 1
   if (ths.length > cap) ths = ths.slice(0, cap);            // 1
   return ths;
}
```
